114	/****************************************************************************
115	 * Name: gpio_set_output
116	 ****************************************************************************/
117	
118	static void gpio_set_output(int pin)
119	{
120	  uint32_t cfg = getreg32(BK7258_GPIO_CFG(pin));
121	
122	  cfg &= ~GPIO_CFG_SECOND_FUNC;  /* GPIO mode (bit6 = 0) */
123	  cfg &= ~GPIO_CFG_OUTPUT_EN;    /* output enable (bit3 active-low: 0 = on) */
124	  cfg &= ~GPIO_CFG_INPUT_EN;     /* input off (bit2: 0=off) */
125	  putreg32(cfg, BK7258_GPIO_CFG(pin));
126	}
