128	/****************************************************************************
129	 * Name: gpio_write
130	 ****************************************************************************/
131	
132	static void gpio_write(int pin, int val)
133	{
134	  uint32_t cfg = getreg32(BK7258_GPIO_CFG(pin));
135	
136	  if (val)
137	    {
138	      cfg |= GPIO_CFG_OUTPUT;
139	    }
140	  else
141	    {
142	      cfg &= ~GPIO_CFG_OUTPUT;
143	    }
144	
145	  putreg32(cfg, BK7258_GPIO_CFG(pin));
146	}
