173	 ****************************************************************************/
174	
175	static void spi_write_byte(uint8_t byte)
176	{
177	  int bit;
178	
179	  for (bit = 7; bit >= 0; bit--)
180	    {
181	      gpio_write(g_active_pins->mosi, (byte >> bit) & 1);
182	      spi_delay();
183	      gpio_write(g_active_pins->sclk, 1);
184	      spi_delay();
185	      gpio_write(g_active_pins->sclk, 0);
186	    }
