331	 * Description:
332	 *   Fill a rectangle (x0,y0)-(x1,y1) with a single RGB565 color.
333	 *   Much smaller than full-screen fill — avoids millions of bit-bangs.
334	 *
335	 ****************************************************************************/
336	
337	static void lcd_fill_rect(uint16_t x0, uint16_t y0,
338	                          uint16_t x1, uint16_t y1,
339	                          uint16_t color)
340	{
341	  uint8_t ca[4];
342	  uint8_t ra[4];
343	  uint8_t hi = (color >> 8) & 0xff;
344	  uint8_t lo = color & 0xff;
345	  int npix = (int)(x1 - x0 + 1) * (int)(y1 - y0 + 1);
346	  int i;
347	
348	  /* CASET */
349	
350	  ca[0] = (x0 >> 8) & 0xff;
351	  ca[1] = x0 & 0xff;
352	  ca[2] = (x1 >> 8) & 0xff;
353	  ca[3] = x1 & 0xff;
354	  lcd_send_cmd_data(0x2a, ca, 4);
355	
356	  /* RASET */
357	
358	  ra[0] = (y0 >> 8) & 0xff;
359	  ra[1] = y0 & 0xff;
360	  ra[2] = (y1 >> 8) & 0xff;
361	  ra[3] = y1 & 0xff;
362	  lcd_send_cmd_data(0x2b, ra, 4);
363	
364	  /* RAMWR + pixel data */
365	
366	  lcd_send_cmd(0x2c);
367	  gpio_write(g_active_pins->dc, 1);
368	  gpio_write(g_active_pins->cs, 0);
369	  for (i = 0; i < npix; i++)
370	    {
371	      spi_write_byte(hi);
372	      spi_write_byte(lo);
373	    }
374	
375	  gpio_write(g_active_pins->cs, 1);
376	}
