378	/****************************************************************************
379	 * Name: sqrt_int — integer square root (Newton's method)
380	 ****************************************************************************/
381	
382	static int16_t sqrt_int(int32_t val)
383	{
384	  int32_t guess;
385	  int32_t next;
386	  int i;
387	
388	  if (val <= 0)
389	    {
390	      return 0;
391	    }
392	
393	  guess = val;
394	
395	  for (i = 0; i < 10; i++)
396	    {
397	      next = (guess + val / guess) / 2;
398	
399	      if (next >= guess)
400	        {
401	          break;
402	        }
403	
404	      guess = next;
405	    }
406	
407	  return (int16_t)guess;
408	}
